def cell_area(i,j):
    r0, c0 = 8+6*i, 14+6*j
    return [a[r0+dr][c0:c0+5] for dr in range(5)]
def sep(i,j,di,dj):
    # separator between (i,j) and neighbor
    r0, c0 = 8+6*i, 14+6*j
    if di==1: return a[r0+5][c0:c0+5]
    if di==-1: return a[r0-1][c0:c0+5]
    if dj==1: return ''.join(a[r][c0+5] for r in range(r0,r0+5))
    return ''.join(a[r][c0-1] for r in range(r0,r0+5))
print('   ' + ' '.join(f'{j:^5}' for j in range(6)))
for i in range(8):
    row=[]
    for j in range(6):
        ar = cell_area(i,j)
        from collections import Counter
        cnt = Counter(ch for s in ar for ch in s)
        row.append(f'{cnt.most_common(1)[0][0]}{cnt.most_common(1)[0][1]:>2}')
    print(i, ' '.join(f'{x:^5}' for x in row))
print('separators (non-B shown):')
for i in range(8):
    for j in range(6):
        for (di,dj,nm) in [(0,1,'R'),(1,0,'D')]:
            ni,nj = i+di, j+dj
